import sqlite3, math, copy, json
from collections import defaultdict, deque

DB_PATH = '/app/manufacturing.db'


def load_db(db_path):
    conn = sqlite3.connect(db_path)
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    parts = {}
    for r in cur.execute('SELECT part_id, name, on_hand_qty, batch_size FROM parts'):
        parts[r['part_id']] = {'name': r['name'], 'on_hand': r['on_hand_qty'], 'batch': r['batch_size']}
    bom_parents = defaultdict(list)
    bom_children = defaultdict(list)
    for r in cur.execute('SELECT parent_part_id, child_part_id, qty_per, scrap_rate_pct, setup_scrap_qty FROM bom'):
        entry = {
            'child': r['child_part_id'],
            'qty_per': r['qty_per'],
            'scrap_rate_pct': r['scrap_rate_pct'],
            'setup_scrap_qty': r['setup_scrap_qty']
        }
        bom_children[r['parent_part_id']].append(entry)
        bom_parents[r['child_part_id']].append(r['parent_part_id'])
    workcenters = {}
    for r in cur.execute('SELECT workcenter_id, name, available_hours FROM workcenters'):
        workcenters[r['workcenter_id']] = r['available_hours']
    routing = defaultdict(list)
    for r in cur.execute('SELECT parent_part_id, workcenter_id, setup_hours, run_hours_per_unit FROM routing'):
        routing[r['parent_part_id']].append({
            'workcenter': r['workcenter_id'],
            'setup': r['setup_hours'],
            'run': r['run_hours_per_unit']
        })
    substitutes = defaultdict(list)
    for r in cur.execute('SELECT primary_part_id, substitute_part_id, qty_ratio, preference_rank FROM substitutes'):
        substitutes[r['primary_part_id']].append({
            'sub': r['substitute_part_id'],
            'ratio': r['qty_ratio'],
            'rank': r['preference_rank']
        })
    for k in substitutes:
        substitutes[k].sort(key=lambda x: (x['rank'], x['sub']))
    orders = []
    for r in cur.execute('SELECT order_id, product_part_id, requested_qty, priority FROM orders ORDER BY priority, order_id'):
        orders.append({
            'order_id': r['order_id'],
            'product': r['product_part_id'],
            'requested_qty': r['requested_qty'],
            'priority': r['priority']
        })
    conn.close()
    leaf_parts = {pid for pid in parts if pid not in bom_children}
    return parts, dict(bom_children), workcenters, dict(routing), substitutes, orders, leaf_parts


def topological_order(all_parts, bom_children):
    # parent -> child edges; topological order where parents precede children
    indeg = {p: 0 for p in all_parts}
    out = defaultdict(list)
    for parent, children in bom_children.items():
        for c in children:
            out[parent].append(c['child'])
            indeg[c['child']] += 1
    q = deque([p for p in all_parts if indeg[p] == 0])
    order = []
    while q:
        p = q.popleft()
        order.append(p)
        for ch in out[p]:
            indeg[ch] -= 1
            if indeg[ch] == 0:
                q.append(ch)
    if len(order) != len(all_parts):
        raise ValueError('Cycle detected or missing part in BOM graph')
    return order


def plan_production(product_id, target_units, parts, bom_children, routing, topo_order):
    req = defaultdict(int)
    req[product_id] += target_units
    production_qty = {}
    leaf_req = defaultdict(int)
    wc_hours = defaultdict(float)
    leaf_parts = {pid for pid in parts if pid not in bom_children}

    for part_id in topo_order:
        required = req.get(part_id, 0)
        if required == 0:
            continue
        if part_id in leaf_parts:
            leaf_req[part_id] += required
            continue
        old = parts[part_id]['on_hand']
        to_make = required - old
        if to_make <= 0:
            production_qty[part_id] = 0
            continue
        batch = parts[part_id]['batch']
        prod = int(math.ceil(to_make / batch) * batch)
        production_qty[part_id] = prod
        # hours for this production run
        for rt in routing.get(part_id, []):
            wc_hours[rt['workcenter']] += rt['setup'] + prod * rt['run']
        # child demands
        for ch in bom_children.get(part_id, []):
            base = ch['qty_per'] * prod
            scrap_mult = 1.0 + ch['scrap_rate_pct'] / 100.0
            child_req = int(math.ceil(base * scrap_mult)) + ch['setup_scrap_qty']
            req[ch['child']] += child_req
    leaf_req_final = {pid: qty for pid, qty in req.items() if pid in leaf_parts and qty > 0}
    return production_qty, leaf_req_final, dict(wc_hours), dict(req)


def satisfy_leaf_requirements(leaf_req, leaf_parts, parts, substitutes):
    """Return (success, updated_leaf_stock_dict)."""
    leaf_stock = {pid: parts[pid]['on_hand'] for pid in leaf_parts}
    remaining = {}
    # First reserve direct primary stock for each leaf demand.
    for leaf_id, qty in leaf_req.items():
        take = min(leaf_stock.get(leaf_id, 0), qty)
        leaf_stock[leaf_id] = leaf_stock.get(leaf_id, 0) - take
        rem = qty - take
        if rem > 0:
            remaining[leaf_id] = rem

    # Then use substitutes for remaining shortages.
    # Process leaf ids in sorted order for determinism.
    for leaf_id in sorted(remaining.keys()):
        shortage = remaining[leaf_id]
        if shortage <= 0:
            continue
        subs = substitutes.get(leaf_id, [])
        for sub in subs:
            if shortage <= 0:
                break
            sub_id = sub['sub']
            sub_stock = leaf_stock.get(sub_id, 0)
            if sub_stock <= 0:
                continue
            ratio = sub['ratio']
            # how many primary units can this substitute cover?
            can_primary = int(math.floor(sub_stock / ratio)) if ratio > 0 else 0
            use_primary = min(shortage, can_primary)
            if use_primary <= 0:
                continue
            need_sub = int(math.ceil(use_primary * ratio))
            if need_sub > sub_stock:
                # adjust if necessary
                use_primary = int(math.floor(sub_stock / ratio))
                need_sub = int(math.ceil(use_primary * ratio))
            leaf_stock[sub_id] = sub_stock - need_sub
            shortage -= use_primary
        remaining[leaf_id] = shortage
        if shortage > 0:
            return False, None
    return True, leaf_stock


def is_feasible(plan, parts, workcenters, leaf_parts, substitutes):
    production_qty, leaf_req, wc_hours, req_all = plan
    for wc, hours in wc_hours.items():
        if workcenters[wc] + 1e-9 < hours:
            return False
    ok, _ = satisfy_leaf_requirements(leaf_req, leaf_parts, parts, substitutes)
    return ok


def execute_plan(plan, parts, leaf_parts, substitutes, workcenters):
    production_qty, leaf_req, wc_hours, req_all = plan
    ok, new_leaf_stock = satisfy_leaf_requirements(leaf_req, leaf_parts, parts, substitutes)
    if not ok:
        raise RuntimeError('Execution of infeasible plan')
    # Update leaf stocks after consumption
    for pid in leaf_parts:
        if pid in new_leaf_stock:
            parts[pid]['on_hand'] = new_leaf_stock[pid]
    # Update non-leaf inventories: old + produced - required (parents used required)
    for part_id, prod in production_qty.items():
        if part_id in leaf_parts:
            continue
        old = parts[part_id]['on_hand']
        required = req_all.get(part_id, 0)
        parts[part_id]['on_hand'] = old + prod - required
    # Update workcenters
    for wc, hours in wc_hours.items():
        workcenters[wc] -= hours


def compute_limiting_resource(product_id, allocated_qty, batch_size, parts, bom_children, routing, topo_order, workcenters, substitutes, leaf_parts):
    # Gross requirement for one more batch than allocated; net out subassemblies, not leaf inventory.
    target = allocated_qty + batch_size
    plan = plan_production(product_id, target, parts, bom_children, routing, topo_order)
    production_qty, leaf_req, wc_hours, _ = plan
    ratios = {}
    # Leaves: available = own stock + substitute-equivalent stock
    for leaf_id in leaf_req:
        avail = parts[leaf_id]['on_hand']
        for sub in substitutes.get(leaf_id, []):
            sub_stock = parts[sub['sub']]['on_hand']
            if sub['ratio'] > 0:
                avail += int(math.floor(sub_stock / sub['ratio']))
        gross = leaf_req[leaf_id]
        if gross > 0:
            ratios[leaf_id] = avail / gross
    # Workcenters
    for wc_id in wc_hours:
        avail = workcenters[wc_id]
        gross = wc_hours[wc_id]
        if gross > 0:
            ratios[wc_id] = avail / gross
    lim = None
    best = None
    for rid, ratio in ratios.items():
        if ratio < 1.0 - 1e-12:
            if best is None or ratio < best - 1e-12 or (abs(ratio-best) <= 1e-12 and rid < lim):
                best = ratio
                lim = rid
    return lim


def solve():
    parts, bom_children, workcenters, routing, substitutes, orders, leaf_parts = load_db(DB_PATH)
    topo_order = topological_order(list(parts.keys()), bom_children)
    report_orders = []

    for order in orders:
        order_id = order['order_id']
        product_id = order['product']
        qty = order['requested_qty']
        batch = parts[product_id]['batch']

        # Snapshot parts before order for limiting-resource computation
        parts_before = copy.deepcopy(parts)
        workcenters_before = copy.deepcopy(workcenters)

        candidates = []
        m = 0
        while m < qty:
            candidates.append(m)
            m += batch
        candidates.append(qty)
        candidates = sorted(set(candidates))

        feasible_target = -1
        feasible_plan = None
        lo, hi = 0, len(candidates)-1
        while lo <= hi:
            mid = (lo + hi)//2
            target = candidates[mid]
            plan = plan_production(product_id, target, parts, bom_children, routing, topo_order)
            if is_feasible(plan, parts, workcenters, leaf_parts, substitutes):
                feasible_target = target
                feasible_plan = plan
                lo = mid + 1
            else:
                hi = mid - 1

        allocated = feasible_target
        if allocated < 0:
            allocated = 0
            feasible_plan = plan_production(product_id, allocated, parts, bom_children, routing, topo_order)

        shortfall = qty - allocated

        # Cancel rule if allocated/requested < 0.5
        if allocated / qty < 0.5:
            allocated_effective = 0
            shortfall_effective = qty
            limiting = compute_limiting_resource(
                product_id, 0, batch, parts_before, bom_children, routing, topo_order,
                workcenters_before, substitutes, leaf_parts
            )
            # Do not consume any inventory or workcenters.
            report_orders.append({
                'order_id': order_id,
                'allocated_qty': allocated_effective,
                'shortfall_qty': shortfall_effective,
                'limiting_resource': limiting
            })
            continue

        if shortfall > 0:
            limiting = compute_limiting_resource(
                product_id, allocated, batch, parts_before, bom_children, routing, topo_order,
                workcenters_before, substitutes, leaf_parts
            )
        else:
            limiting = None

        report_orders.append({
            'order_id': order_id,
            'allocated_qty': allocated,
            'shortfall_qty': shortfall,
            'limiting_resource': limiting
        })

        # execute actual feasibility plan
        if allocated > 0:
            execute_plan(feasible_plan, parts, leaf_parts, substitutes, workcenters)

    report_orders.sort(key=lambda x: x['order_id'])
    with open('/app/report.json', 'w') as f:
        json.dump({'orders': report_orders}, f, indent=2)
    return report_orders, parts, workcenters


